// Fixture loading for the H.264 decoder tests. Fixtures are Annex B streams generated by tools/codecs/
// New-H264Fixtures.ps1, with the decode-order presentation timestamps (.pts, milliseconds) and FFmpeg's per-frame
// MD5 reference in output order (.framemd5). Access units are recovered from the byte stream: a new one starts at an
// access unit delimiter, SPS, PPS or SEI after a slice, or at a slice with first_mb_in_slice equal to 0.

using System.Security.Cryptography;
using RTSP.IngestService.Media.Codecs;
using RTSP.IngestService.Media.Codecs.Video.H264;

namespace RTSP.IngestService.Tests.Media.Codecs.H264;

/// <summary>A decoded frame's comparable properties.</summary>
/// <param name="Timestamp">The timestamp.</param>
/// <param name="Md5">The MD5 of the packed Y, Cb and Cr planes, lowercase hex.</param>
/// <param name="Width">The width.</param>
/// <param name="Height">The height.</param>
/// <param name="IsKeyframe">Whether it is an IDR picture.</param>
internal readonly record struct DecodedFrameInfo(long Timestamp, string Md5, int Width, int Height, bool IsKeyframe);

/// <summary>H.264 fixture helpers.</summary>
internal static class H264TestSupport
{
    /// <summary>The fixture time base (Matroska milliseconds).</summary>
    public static readonly MediaTimeBase TimeBase = new(1, 1000);

    /// <summary>Gets the fixture directory.</summary>
    public static string FixtureDirectory => Path.Combine(AppContext.BaseDirectory, "Media", "Codecs", "Fixtures");

    /// <summary>Gets the decodable fixtures with their coded size and frame count.</summary>
    public static TheoryData<string, int, int, int> DecodableFixtures => new()
    {
        { "baseline-cavlc-176x144", 176, 144, 30 },
        { "constrained-baseline-openh264-320x240", 320, 240, 24 },
        { "main-cabac-bpyramid-weightp-320x240", 320, 240, 36 },
        { "high-8x8-temporal-cqm-352x288", 352, 288, 30 },
        { "high-cavlc-8x8-256x192", 256, 192, 30 },
        { "high-cropped-slices-bt709-198x110", 198, 110, 20 },
        { "high-intra-160x96", 160, 96, 8 },
        { "mf-high-320x240", 320, 240, 20 },
        { "nvenc-high-bframes-320x240", 320, 240, 24 },
    };

    /// <summary>Gets the names of the decodable fixtures.</summary>
    public static string[] DecodableFixtureNames =>
    [
        "baseline-cavlc-176x144", "constrained-baseline-openh264-320x240", "main-cabac-bpyramid-weightp-320x240",
        "high-8x8-temporal-cqm-352x288", "high-cavlc-8x8-256x192", "high-cropped-slices-bt709-198x110", "high-intra-160x96",
        "mf-high-320x240", "nvenc-high-bframes-320x240",
    ];

    /// <summary>Reads a fixture's access units in decode order, Annex B framed.</summary>
    /// <param name="name">The fixture name without the h264- prefix.</param>
    /// <returns>The access units.</returns>
    public static List<byte[]> ReadAccessUnits(string name) => SplitAccessUnits(File.ReadAllBytes(Path.Combine(FixtureDirectory, $"h264-{name}.h264")));

    /// <summary>Reads a fixture's decode-order timestamps.</summary>
    /// <param name="name">The fixture name.</param>
    /// <returns>The timestamps.</returns>
    public static long[] ReadTimestamps(string name) =>
        [.. File.ReadAllLines(Path.Combine(FixtureDirectory, $"h264-{name}.pts")).Where(static l => l.Length > 0).Select(long.Parse)];

    /// <summary>Reads FFmpeg's reference: per output frame, the MD5.</summary>
    /// <param name="name">The fixture name.</param>
    /// <returns>The hashes in output order.</returns>
    public static List<string> ReadReference(string name) =>
        [.. File.ReadAllLines(Path.Combine(FixtureDirectory, $"h264-{name}.framemd5"))
            .Where(static l => l.Length > 0 && l[0] != '#')
            .Select(static l => l.Split(',')[^1].Trim())];

    /// <summary>Splits an Annex B stream into NAL units (without start codes).</summary>
    /// <param name="data">The stream.</param>
    /// <returns>The NAL units.</returns>
    public static List<byte[]> SplitNalUnits(byte[] data)
    {
        var units = new List<byte[]>();
        var starts = new List<(int Start, int Payload)>();
        for (var i = 0; i + 2 < data.Length; i++)
        {
            if (data[i] == 0 && data[i + 1] == 0 && data[i + 2] == 1)
            {
                starts.Add((i > 0 && data[i - 1] == 0 ? i - 1 : i, i + 3));
                i += 2;
            }
        }

        for (var k = 0; k < starts.Count; k++)
        {
            var end = k + 1 < starts.Count ? starts[k + 1].Start : data.Length;
            units.Add(data[starts[k].Payload..end]);
        }

        return units;
    }

    /// <summary>Groups an Annex B stream into access units.</summary>
    /// <param name="data">The stream.</param>
    /// <returns>Annex B access units with 4-byte start codes.</returns>
    public static List<byte[]> SplitAccessUnits(byte[] data)
    {
        var result = new List<byte[]>();
        var current = new List<byte[]>();
        var hasSlice = false;
        foreach (var nal in SplitNalUnits(data))
        {
            var type = nal[0] & 0x1F;
            var isSlice = type is 1 or 5;
            var startsPicture = isSlice && (nal[1] & 0x80) != 0;
            if (hasSlice && (type is 6 or 7 or 8 or 9 || startsPicture))
            {
                result.Add(Join(current));
                current.Clear();
                hasSlice = false;
            }

            current.Add(nal);
            hasSlice |= isSlice;
        }

        if (current.Count > 0)
        {
            result.Add(Join(current));
        }

        return result;
    }

    /// <summary>Joins NAL units with 4-byte start codes.</summary>
    /// <param name="units">The units.</param>
    /// <returns>The Annex B bytes.</returns>
    public static byte[] Join(IEnumerable<byte[]> units)
    {
        using var stream = new MemoryStream();
        foreach (var unit in units)
        {
            stream.Write([0, 0, 0, 1]);
            stream.Write(unit);
        }

        return stream.ToArray();
    }

    /// <summary>Converts an Annex B access unit to 4-byte length-prefixed NAL units, dropping parameter sets.</summary>
    /// <param name="accessUnit">The access unit.</param>
    /// <returns>The length-prefixed access unit.</returns>
    public static byte[] ToLengthPrefixed(byte[] accessUnit)
    {
        using var stream = new MemoryStream();
        foreach (var unit in SplitNalUnits(accessUnit))
        {
            if ((unit[0] & 0x1F) is 7 or 8)
            {
                continue;
            }

            stream.Write([(byte)(unit.Length >> 24), (byte)(unit.Length >> 16), (byte)(unit.Length >> 8), (byte)unit.Length]);
            stream.Write(unit);
        }

        return stream.ToArray();
    }

    /// <summary>Builds an AVCDecoderConfigurationRecord from the first SPS and PPS of a stream.</summary>
    /// <param name="accessUnit">An access unit containing the parameter sets.</param>
    /// <returns>The record.</returns>
    public static byte[] BuildAvcC(byte[] accessUnit)
    {
        var units = SplitNalUnits(accessUnit);
        var sps = units.First(static u => (u[0] & 0x1F) == 7);
        var pps = units.First(static u => (u[0] & 0x1F) == 8);
        using var stream = new MemoryStream();
        stream.Write([1, sps[1], sps[2], sps[3], 0xFF, 0xE1, (byte)(sps.Length >> 8), (byte)sps.Length]);
        stream.Write(sps);
        stream.Write([1, (byte)(pps.Length >> 8), (byte)pps.Length]);
        stream.Write(pps);
        return stream.ToArray();
    }

    /// <summary>Hashes a frame like FFmpeg's framemd5 of yuv420p rawvideo.</summary>
    /// <param name="frame">The frame.</param>
    /// <returns>Lowercase hex MD5.</returns>
    public static string Md5(VideoFrame frame)
    {
        using var md5 = IncrementalHash.CreateHash(HashAlgorithmName.MD5);
        for (var plane = 0; plane < 3; plane++)
        {
            md5.AppendData(frame.GetPlane(plane));
        }

        return Convert.ToHexStringLower(md5.GetHashAndReset());
    }

    /// <summary>Hashes packed planar bytes like FFmpeg's framemd5.</summary>
    /// <param name="data">The bytes.</param>
    /// <returns>Lowercase hex MD5.</returns>
    public static string Md5(ReadOnlySpan<byte> data)
    {
        using var md5 = IncrementalHash.CreateHash(HashAlgorithmName.MD5);
        md5.AppendData(data);
        return Convert.ToHexStringLower(md5.GetHashAndReset());
    }

    /// <summary>Decodes access units and drains, disposing every frame after recording it.</summary>
    /// <param name="decoder">The decoder.</param>
    /// <param name="accessUnits">The access units.</param>
    /// <param name="timestamps">Timestamps per access unit, or <see langword="null"/> to use the index.</param>
    /// <returns>The frames in output order.</returns>
    public static List<DecodedFrameInfo> DecodeAll(H264Decoder decoder, IReadOnlyList<byte[]> accessUnits, IReadOnlyList<long>? timestamps = null)
    {
        var result = new List<DecodedFrameInfo>();
        var frames = new List<VideoFrame>();
        for (var i = 0; i < accessUnits.Count; i++)
        {
            decoder.Decode(new EncodedPacket(accessUnits[i], timestamps?[i] ?? i, TimeBase), frames);
            Collect(frames, result);
        }

        decoder.Drain(frames);
        Collect(frames, result);
        return result;
    }

    /// <summary>Records and disposes frames.</summary>
    /// <param name="frames">The frames; cleared.</param>
    /// <param name="result">Receives the records.</param>
    public static void Collect(List<VideoFrame> frames, List<DecodedFrameInfo> result)
    {
        foreach (var frame in frames)
        {
            result.Add(new DecodedFrameInfo(frame.Timestamp, Md5(frame), frame.Width, frame.Height, frame.IsKeyframe));
            frame.Dispose();
        }

        frames.Clear();
    }

    /// <summary>Creates an Annex B decoder.</summary>
    /// <param name="options">Limits, or <see langword="null"/>.</param>
    /// <returns>The decoder.</returns>
    public static H264Decoder CreateAnnexB(H264DecoderOptions? options = null)
    {
        var decoder = new H264Decoder(options);
        decoder.Configure(H264DecoderConfiguration.AnnexB);
        return decoder;
    }
}
